/* ######## Footer Css ######################### */
.foot-bar-social {
padding: 10px 0;
}
.foot-bar-social li {
padding: 0;
    display: inline-block;
    float: none;
margin-right: 5px;
;
}
.foot-bar-social .widget ul {
padding: 0;
}
.foot-bar-social .LinkList ul {
text-align: center;
}
.foot-bar-social #social a {
display: block;
width: 30px;
height: 30px;
line-height: 30px;
font-size: 15px;
color: #ebebeb;
}
.foot-bar-social #social a:hover {
color:$maincolor;
}
.foot-bar-social #social a:before {
display: inline-block;
font: normal normal normal 22px/1 FontAwesome;
font-size: inherit;
font-style: normal;
