.top-bar-social .snapchat:before, .foot-bar-social .snapchat:before { content: "\f2ac"; }
.top-bar-social .reddit:before, .foot-bar-social .reddit:before { content: "\f1a1"; }
.top-bar-social .medium:before, .foot-bar-social .medium:before { content: "\f23a"; }
