.top-bar-social .xing:before, .foot-bar-social .xing:before { content: "\f168"; }
.top-bar-social .quora:before, .foot-bar-social .quora:before { content: "\f2c4"; }
.top-bar-social .google:before, .foot-bar-social .google:before { content: "\f1a0"; }
.top-bar-social .podcast:before, .foot-bar-social .podcast:before { content: "\f2ce"; }
